import logging

from openupgradelib import openupgrade

_logger = logging.getLogger(__name__)


@openupgrade.migrate()
def migrate(env, version):
    # Calendars generated by hr_employee_calendar_planning had 0 hours per day.
    calendars = (
        env["resource.calendar"]
        .with_context(active_test=False)
        .search([("stored_hours_per_day", "=", 0)])
    )
    env.add_to_compute(
        env["resource.calendar"]._fields["stored_hours_per_day"], calendars
    )
    env.flush_all()
    _logger.info(
        "Hours per day recomputed on %s calendars, %s still at 0",
        len(calendars),
        len(calendars.filtered(lambda c: not c.stored_hours_per_day)),
    )
